/*
 * A170557  Number of reduced words of length n in Coxeter group on 20
 *          generators S_i with relations (S_i)^2 = (S_i S_j)^47 = I.
 * https://oeis.org/A170557
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 1, u16 n <= 3, u32 n <= 7, u64 n <= 15, u128 n <= 15,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A170557: Number of reduced words of length n in the Coxeter
 * group generated by 20 elements with relations (S_i)^2 = (S_i S_j)^47 = I.
 *
 * The ordinary generating function is
 *     (t^47 + 2 t^46 + … + 2 t + 1) /
 *     (171 t^47 - 18 t^46 - … - 18 t + 1).
 *
 * Let D(t)=1-18t-18t^2-…-18t^46+171t^47 and N(t)=1+2t+…+2t^46+t^47.
 * Then D(t)·A(t)=N(t).
 *
 * Coefficient recurrence (valid for all n≥0, a(k)=0 for k<0):
 *     a(n) = 18·∑_{k=1}^{46} a(n-k) - 171·(n≥47? a(n-47) : 0) + N_n
 *
 * where N_n = 1 for n=0 or n=47, N_n = 2 for 1≤n≤46, and N_n = 0 for n>47.
 */

#include <stdlib.h>

/*--- static cache ----------------------------------------------------*/

static seq_t *cache = NULL;        /* array of computed terms  */
static idx_t cached_size = 0;      /* number of terms currently stored  */

/*--- ensure_cache: extends cache up to index n ----------------------*/

static void ensure_cache(idx_t n)
{
    if (n < cached_size) return;

    idx_t new_size = n + 1;
    seq_t *new_cache = (seq_t *)realloc(cache, new_size * sizeof(seq_t));
    if (!new_cache) exit(EXIT_FAILURE);
    cache = new_cache;

    for (idx_t i = cached_size; i < new_size; ++i)
    {
        /* compute sum of the 46 previous terms that exist */
        seq_t sum = 0;
        idx_t kmax = (i < 46) ? i : 46;
        for (idx_t k = 1; k <= kmax; ++k)
            sum += cache[i - k];

        /* numerator coefficient N_i */
        seq_t N = 0;
        if (i == 0 || i == 47)
            N = 1;
        else if (i <= 46)
            N = 2;

        /* recurrence */
        seq_t val = (seq_t)18 * sum;
        if (i >= 47)
            val -= (seq_t)171 * cache[i - 47];
        val += N;

        cache[i] = val;
    }
    cached_size = new_size;
}

/*--- public function -------------------------------------------------*/

seq_t a(idx_t n)
{
    ensure_cache(n);
    return cache[n];
}
